INSERT INTO ft_training.grammar_questions VALUES
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-01','What color is it?','It''s a yellow.','It''s yellow.','1','“Yellow” is a color adjective, so we don''t use “a” before it when simply describing the color.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-02','Which one is correct?','Do you know what is his hobby?','Do you know what his hobby is?','1','In an indirect question, the word order changes to subject + verb: “what his hobby is,” not “what is his hobby.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-03','THe sentence pattern is "These are sneakers." What is the correct question to ask?','What are these?','What''s this?','0','Because “these” is plural, we use “are.” The question follows the pattern What + are + these?'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-04','She (like, likes) playing basketball.','like','likes','1','Use “likes” because “she” is a singular subject. In the simple present tense, the verb takes -s with he/she/it.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-05','Which sentence is correct?','She go to school yesterday.','She went to school yesterday.','1','“Yesterday” shows that the action happened in the past, so we use the past tense “went,” not “go.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-06','What''s this?','It''s a bumper cars.','It''s a bumper car.','1','Use “a bumper car” because the question asks about one thing: “What’s this?”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-07','Is this a bumper cars?','Yes, these are bumper cars','Yes, this is bumper cars','0','Yes, these are bumper cars target word is in plural form'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-08','Do you like bumpers cars?','Yes, I do','Yes, I like','0','Yes, I do-is grammatically correct as a direct short answer and It starts with the auxiliary verb “Do.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-09','Did you play here at the Play Zone?','Yes, I do','Yes, I did.','1','The question starts with “Did”, so the short answer should use “did.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-10','Are these red tomatoes and bell peppers?','Yes, these are red tomatoes and bell peppers','Yes, It is red tomatoes and bell peppers','0','These are a red tomatoes and bell peppers-subject are in both in plural form'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-11','Which one is correct?','What can a bird do?','What bird can do?','0','What can a bird do? → A bird can fly.
INSERT INTO ft_training.assessment_rules VALUES
('ft-target-words-v2-round-v1-grammar-20260920','word','30','80','{"score_formula":"pronunciation","rounding_decimal_places":1,"all_items_must_pass":true,"retry_failed_item":true,"prerequisite":null}','第一关：随机抽30个单词；发音分四舍五入到1位小数，每题至少80分，全部通过后解锁第二关。'),
('ft-target-words-v2-round-v1-grammar-20260920','sentence','20','80','{"score_formula":"(pronunciation*0.85+fluency*0.10+rhythm*0.05)*integrity/100","rounding_decimal_places":1,"all_items_must_pass":true,"retry_failed_item":true,"prerequisite":"word"}','第二关：随机抽20个句子；（发音×85%＋流利度×10%＋韵律×5%）×完整度/100，四舍五入到1位小数，每题至少80分，全部通过后解锁第三关。'),
('ft-target-words-v2-round-v1-grammar-20260920','grammar','30','80','{"required_correct":24,"max_wrong":6,"fail_on_wrong_number":7,"attempts_per_question":1,"sequential":true,"wrong_answer_reveals_solution":false,"wrong_answer_can_continue":true,"shuffle_on_failed_reentry":true,"resume_unfinished":true,"prerequisite":"sentence"}','第三关：30题，每题只提交一次，按顺序作答，答错标记错误且不揭示答案。完成后至少答对24题通过；累计错7题立即结束，重考打乱顺序。未完成时保留进度。');
INSERT INTO ft_training.schema_versions VALUES(2,now());
