BEGIN;
CREATE TABLE ft_training.content_versions(version text PRIMARY KEY, source_description text NOT NULL, source_sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ft_training.speech_questions(content_version text NOT NULL REFERENCES ft_training.content_versions(version), id text NOT NULL, kind text NOT NULL CHECK(kind IN ('word','sentence')), text text NOT NULL, metadata jsonb NOT NULL, PRIMARY KEY(content_version,id));
CREATE TABLE ft_training.assessment_rules(content_version text NOT NULL REFERENCES ft_training.content_versions(version), stage text NOT NULL CHECK(stage IN ('word','sentence','grammar')), question_count integer NOT NULL CHECK(question_count>0), pass_percent integer NOT NULL CHECK(pass_percent BETWEEN 0 AND 100), settings jsonb NOT NULL, description_zh text NOT NULL, PRIMARY KEY(content_version,stage));
COMMENT ON TABLE ft_training.speech_questions IS '第一关单词与第二关句子题库；按版本保存';
COMMENT ON TABLE ft_training.grammar_questions IS '第三关语法题、两个选项、正确选项与原始解析';
COMMENT ON TABLE ft_training.assessment_rules IS '三关抽题、评分、通过、解锁与重考规则；保存配置不等于应用已接入';
“Can” comes before the subject when asking about ability.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-12','Which one is correct?','What''s this? (bumper cars)','What are thse?(bumper cars)','1','Bunper cars-target word is in plural form'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-13','Which one is correct?','teacher will give you a fries.','teacher will give you some fries','1','“A fries” is incorrect. Fries is plural, so we cannot use “a” before it.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-14','What is it?','It''s a beef.','It''s beef.','1','It’s a beef. — generally incorrect when identifying the type of meat.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-15','Which one is correct?','What are the advices that the dietitian gave?”','What pieces of advice did the dietitian give?','1','Advice is an uncountable noun in English. We do not normally make it plural as “advices.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-16','Which one is correct?','Do you like playing the trampoline?','Do you like playing on the trampoline?','1','We use “on” because a trampoline is a surface that you jump/play on.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-17','Which one is correct?','What can a bird do?','What does a bird can do?','0','Can is already a helping/modal verb, so we don''t use does with it.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-18','Do you have a yellow bear?','Yes, I do.','Yes, I have.','0','The question starts with “Do you have…?”, so we use do in the short answer.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-19','What made this sentence wrong? "Practice with an English teachers everyday."','an English teacher','English teachers','0','“An” is used only with a singular countable noun. Since “teachers” is plural, we should say “English teachers.”'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-20','Which question is correct?','What a bird can do?','What can a bird do?','1','For a WH-question, we usually put the helping/modal verb before the subject.

What + can + subject + verb?'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-21','Which of these sentences is correct?
','She need to answer in a complete sentences.','She needs to answer in a complete sentence.','1','With she/he/it, the verb takes -s: "A” is singular, so sentence should not be plural.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-22','Which question is correct?','Is junkfoods healthy or unhealthy?','Is junk food healthy or unhealthy?','1','“junk food” is usually treated as an uncountable noun, so we don''t normally add -s.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-23','Which question is correct?','Does she like doing yoga?','Does she likes doing yoga?','0','When we use “does,” the main verb stays in its base form.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-24','Which question is correct?','Why does he like playing soccer?','Why does he likes playing soccer?','0','After “does,” use the base form of the verb.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-25','Which question is correct?','Whose feet are bigger?','Whose feet is bigger?','0','Feet is the plural form of foot, so we use are, not is.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-26','Which question is correct?','Who likes watching movies in your family?','Who like watching movies in your family?','0','who refers to one person in the family, so we use likes.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-27','Which question is correct?','What color are your shorts?','What color is your shorts?','0','Shorts is a plural noun, so we use are, not is.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-28','How many pairs of sneakers do you have?','I have three pairs of sneakers.','I have a three pairs of sneakers.','0','We do not use “a” before a plural number.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-29','What is she wearing?','She’s wearing a sweater, a skirt, and boots.','She’s wearing a sweater, a skirt, and a boots.','0','Boots is a plural noun, so we don''t use “a” before it.'),
('ft-target-words-v2-round-v1-grammar-20260920','ft-grammar-20260920-30','What is he doing?','He plays guitar.','He is playing the guitar.','1','he question “What is he doing?” asks about an action happening now.');
COMMIT;
